  /\ L5.u64_at RSEGS M (sp - 24) (bv_unsigned (getr R (reg 9))) /\ L5.u64_at RSEGS M (sp - 16) (bv_unsigned (getr R (reg 8))) /\ L5.u64_at RSEGS M (sp - 8) r.

